{"packet_id":"D041-01","doc_id":"D041","jurisdiction":"Los Angeles, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"RSO allowable rent increase","requirement":"Rent for covered units may be raised only once every 12 months by the allowable rent increase percentage. From February 2, 2026, landlords may no longer add a utility percentage increase or a 10% increase for a dependent.","key_value":"1 increase per 12 months; utility and dependent add-on percentage increases barred from 2026-02-02","coverage_conditions":"Rental properties first built on or before October 1, 1978, including apartments, duplexes, ADUs, mobile homes, and rooms occupied more than 30 consecutive days.","applicability":{"built_on_or_before":"1978-10-01","built_after":null,"date_basis":"construction_date","min_units":null,"max_units":null,"owner_dependent":false,"other":"Replacement units under LAMC Section 151.28 are also covered."},"exemptions":"Condominium and townhome tenancies commencing after December 31, 1995, where the rent amount is not regulated; luxury exemption for units with rent charged on or before May 31, 1978.","penalty":null,"effective_date":"2026-02-02","citation":"L.A. Mun. Code ch. XV (Rent Stabilization Ordinance)","quoted_span":"Rent may be increased once every 12 months by the allowable rent increase percentage (click here to view the allowable rent increase PDF). Effective February 2, 2026, the landlord can no longer include an additional percentage increase for utilities.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D041-01","doc_id":"D041","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"RSO legal reasons for eviction and relocation assistance","requirement":"A landlord may terminate an RSO tenancy only for the listed at-fault or no-fault reasons, must file the notice with LAHD within three business days of service, and must pay relocation assistance for no-fault evictions.","key_value":"relocation assistance for no-fault evictions; 30-day and 60-day notice (up to 120 days or 1-year extension)","coverage_conditions":"All rental units subject to the City of Los Angeles Rent Stabilization Ordinance.","applicability":{"built_on_or_before":"1978-10-01","built_after":null,"date_basis":"construction_date","min_units":null,"max_units":null,"owner_dependent":false,"other":null},"exemptions":null,"penalty":null,"effective_date":null,"citation":"L.A. Mun. Code § 151.09","quoted_span":"No-fault evictions require the payment of relocation assistance. Checklist for No-Fault Evictions File a Landlord Declaration of Intent to Evict filed with the LAHD. Give the tenant a 30-day and 60-day written notice (some evictions require 120-day notice or up to a 1-year extension). Payment of tenant relocation assistance.","interaction":"Units not covered by the RSO are subject to the City's Just Cause Ordinance.","confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D041-01","doc_id":"D041","jurisdiction":"Los Angeles, CA","category":"security_deposits","lifecycle":"enacted","title":"RSO security deposit interest payments","requirement":"The Rent Stabilization Ordinance covers interest payments on security deposits, so landlords of RSO units must make the interest payments the ordinance requires on tenant deposits.","key_value":null,"coverage_conditions":"Rental units covered by the City of Los Angeles Rent Stabilization Ordinance.","applicability":{"built_on_or_before":"1978-10-01","built_after":null,"date_basis":"construction_date","min_units":null,"max_units":null,"owner_dependent":false,"other":null},"exemptions":null,"penalty":null,"effective_date":null,"citation":"L.A. Mun. Code ch. XV (Rent Stabilization Ordinance)","quoted_span":"Interest Payments on Security Deposits","interaction":null,"confidence":0.35,"conflict_flag":false,"conflict_note":null}
